export const guides=[
 {id:'communication',keywords:'communication feedback clear instructions 沟通 反馈 指令',en:{title:'Make communication a little clearer',intro:'Communication preferences differ. A shared plan can reduce guesswork for everyone.',steps:['Ask whether written or spoken instructions are easier to use.','Agree on one concrete next step and a realistic time to reply.','Check your understanding with a brief summary, without assuming intent.'],prompt:'Would a written example help, or would you prefer to talk it through?'},zh:{title:'让沟通更清楚一点',intro:'每个人的沟通偏好不同。一起约定方式，可以减少彼此的猜测。',steps:['询问对方更容易理解书面还是口头说明。','一起约定一个具体的下一步，以及合适的回复时间。','用简短的总结确认理解，不急着猜测对方的意图。'],prompt:'书面的例子会有帮助吗？还是你更想一起聊一聊？'},url:'https://www.autism.org.uk/advice-and-guidance/about-autism/autism-and-communication',source:'National Autistic Society · Communication'},
 {id:'studying',keywords:'studying deadlines group work planning 学习 截止日期 小组 作业',en:{title:'Find a manageable first step',intro:'For a shared assignment, make expectations visible and agree on a plan together.',steps:['Write down the task, the first small step and the deadline.','Agree who does what; keep instructions in a place both people can revisit.','If you need formal support, ask your university’s support team about available adjustments.'],prompt:'What is one small part we could start with, and when should we check in?'},zh:{title:'找到一个能开始的小步骤',intro:'做共同作业时，把要求写清楚，再一起制定计划。',steps:['写下任务、第一个小步骤与截止日期。','约定各自的分工，把说明放在双方都能重新查看的地方。','如果需要正式支持，可以向大学支持部门询问可提供哪些调整。'],prompt:'我们可以先做哪一小部分？什么时候再互相确认进度？'},url:'https://www.washington.edu/drs/students/using-accommodations/',source:'University of Washington · Using accommodations'},
 {id:'sensory',keywords:'sensory noise light campus quiet 感官 噪音 灯光 安静 校园',en:{title:'Make room for sensory preferences',intro:'A place that feels comfortable to one person may be difficult for another. Ask rather than assume.',steps:['Ask about noise, lighting and seating before choosing where to meet.','Offer a quieter space, a short break or a text conversation if the person wants one.','Agree on a simple way to pause or leave without needing a long explanation.'],prompt:'Is this place comfortable, or would a quieter space or text chat suit you better?'},zh:{title:'给感官偏好留一点空间',intro:'对一个人舒服的环境，对另一个人可能很难适应。先询问，不预设。',steps:['选择见面地点前，询问对噪音、灯光与座位的偏好。','如果对方愿意，可以换个安静的地方、短暂休息，或改用文字交流。','约定一个简单的暂停或离开方式，无需长篇解释。'],prompt:'这里舒服吗？还是安静一点的地方或文字聊天更适合你？'},url:'https://www.autism.org.uk/learn/knowledge-hub/guides-and-resources/accessible-environments',source:'National Autistic Society · Accessible environments'},
 {id:'adjustments',keywords:'adjustments accommodations adviser university support 支持 调整 便利措施 大学 导师',en:{title:'Prepare for a university support conversation',intro:'Support processes differ between universities and countries. Your own university can explain its options.',steps:['Describe a specific barrier and what change would help you take part.','Ask which office handles student or staff adjustments, and what information it needs.','Request a written summary of agreed next steps; share only the personal details needed.'],prompt:'Who could we ask about support for this situation, and what would you like them to know?'},zh:{title:'为大学支持咨询做一点准备',intro:'不同大学与国家的支持流程有所不同。你所在的大学可以说明具体选项。',steps:['描述一个具体的困难，以及什么改变能帮助你参与。','询问哪个部门负责学生或员工的支持与调整，以及需要哪些信息。','请对方书面总结约定的下一步；只分享必要的个人细节。'],prompt:'这种情况可以向谁咨询支持？你希望他们了解哪些事情？'},url:'https://www.washington.edu/drs/students/using-accommodations/',source:'University of Washington · Using accommodations'},
 {id:'preferences',keywords:'preferences boundaries consent neurodiversity autism ADHD dyslexia 偏好 边界 同意 神经多样性 自闭症 多动症 阅读障碍',en:{title:'Start with the person, not the label',intro:'Neurodivergent is a broad umbrella. A label does not tell you someone’s preferences, and autism resources do not describe every neurodivergent experience.',steps:['Ask how the person describes themselves and respect their wording.','Ask whether they want listening, ideas or practical help today.','Agree on boundaries, including how often to message and how to pause.'],prompt:'Would you like me to listen, offer ideas, or help with one practical step?'},zh:{title:'先了解这个人，再了解标签',intro:'神经多样性是一个宽泛的概念。一个标签不能告诉你一个人的偏好，自闭症相关资料也不能代表所有神经多样性经历。',steps:['询问对方如何描述自己，并尊重他们使用的词语。','询问今天想要的是倾听、建议，还是实际帮助。','一起约定边界，包括联系频率与如何暂停。'],prompt:'你希望我先听你说，分享一些想法，还是帮助你做一个实际的小步骤？'},url:'https://www.autism.org.uk/advice-and-guidance/about-autism',source:'National Autistic Society · About autism (autism-specific resource)'}
];
